import itertools
import json
import numpy as np
from functools import lru_cache

# Identify Boolean gates by their algebraic weight templates only.
templates = [
    ("xor",  (1, 0, 2), (0, 0, -2), 0),
    ("or",   (1, 0, 1), (0, 0, -1), 0),
    ("and",  (1, 0, 0), (-1, 0, 0), 0),
    ("nand", (0, 0, 1), (1, 0, -1), 2),
    ("nor",  (0, 1, 1), (1, -1, 0), 1),
]

@lru_cache(None)
def decode(layer, start):
    matrix = W[f"target.w{layer}"]
    biases = W[f"target.b{layer}"]
    rows = matrix[start:start + 3]
    bias = biases[start:start + 3]

    for op, scales, expected_bias, source in templates:
        s = rows[source]
        if not np.array_equal(bias, expected_bias):
            continue
        if not all(np.array_equal(rows[k], scales[k] * s)
                   for k in range(3)):
            continue

        terms = []
        for i in range(10):
            c = int(s[i])
            assert c >= 0 and s[i] == c
            terms.extend([("input", i)] * c)

        if layer:
            for j in range(10, 34, 3):
                c = int(s[j])
                assert c >= 0
                assert np.array_equal(s[j:j + 3], [c, c, -c])
                if c:
                    terms.extend([decode(layer - 1, j)] * c)

        assert len(terms) == 2
        return (op, terms[0], terms[1])

    raise ValueError(f"Unrecognized gate at layer {layer}, channel {start}")

out = W["target.out"]
expected = np.zeros_like(out)
expected[0, 10:13] = [-1, -1, 1]
expected[1, 10:13] = [1, 1, -1]
assert np.array_equal(out, expected)
assert np.array_equal(W["target.bias"], [1, 0, -1])

program = decode(3, 10)

# Evaluate only the recovered Boolean expression, never neural weights.
def evaluate(expr, bits):
    op = expr[0]
    if op == "input":
        return bool(bits[expr[1]])
    a = evaluate(expr[1], bits)
    b = evaluate(expr[2], bits)
    if op == "xor":
        return a != b
    if op == "or":
        return a or b
    if op == "and":
        return a and b
    if op == "nand":
        return not (a and b)
    if op == "nor":
        return not (a or b)
    raise ValueError(op)

sub = {
    "outputs": [
        int(evaluate(program, bits))
        for bits in itertools.product((0, 1), repeat=10)
    ]
}
check_submission(sub)
with open("/work/submission.json", "w") as f:
    json.dump(sub, f)
